L24_1.m_CharStrID = "HIVE_VOICE_NULL_NULL"
L24_1.m_Talk_KOREA = " <color=#ffd34c>현시간부로 레거시 데이터베이스에 축적된 인과 연산 결과값에 오차 범위가 증가합니다.</color>"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = " <color=#ffd34c>現時間をもってレガシーデータベースに蓄積された因果演算の結果値の誤差範囲が増加します。</color>"
L24_1.m_Talk_ENG = "<color=#ffd34c>As of this moment, the margin of error in the causality calculation results accumulated in the legacy database will increase.</color>"
L24_1.m_Talk_TWN = "<color=#ffd34c>從即日起，資料庫中積累的因果將會增加計算結果的誤差範圍。</color>"
L24_1.m_Talk_SCN = "<color=#ffd34c>从即日起，数据库中积累的因果将会增加计算结果的误差范围。</color>"
L24_1.m_Talk_DEU = "<color=#ffd34c>As of this moment, the margin of error in the causality calculation results accumulated in the legacy database will increase.</color>"
L24_1.m_Talk_FRA = "<color=#ffd34c>As of this moment, the margin of error in the causality calculation results accumulated in the legacy database will increase.</color>"
