L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L27_1.m_Talk_KOREA = " 결국, 이 세계도 어떻게든 여기까지 도달하는 데 성공했군."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = " 結局、この世界も何とかここまでたどり着くことに成功したな。"
L27_1.m_Talk_ENG = "So, this world has also succeeded in reaching this point."
L27_1.m_Talk_TWN = "所以，這個世界也達到了臨界點。"
L27_1.m_Talk_SCN = "所以，这个世界也达到了临界点。"
L27_1.m_Talk_DEU = "So, this world has also succeeded in reaching this point."
L27_1.m_Talk_FRA = "So, this world has also succeeded in reaching this point."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "YAKSHA_ACT3_STAGE1_START@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 6400301
L28_1.m_CutScenStrID = "YAKSHA_ACT3_STAGE1_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L28_1.m_Talk_KOREA = " 이 지점부터는 하이브 컨트롤의 연산으로도 모든 걸 완벽히 예측할 수는 없어."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = " この時点からは、ハイブコントロールの演算でもすべてのことを完璧に予測することはできない。"
L28_1.m_Talk_ENG = "From this point on, not even Hive Control's calculations can perfectly predict everything."
L28_1.m_Talk_TWN = "從現在開始，即使是巢穴控制系統也無法百分百地預測一切了。"
L28_1.m_Talk_SCN = "从现在开始，即使是巢穴控制系统也无法百分百地预测一切了。"
L28_1.m_Talk_DEU = "From this point on, not even Hive Control's calculations can perfectly predict everything."
L28_1.m_Talk_FRA = "From this point on, not even Hive Control's calculations can perfectly predict everything."
L29_1 = {}
