L29_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L29_1.m_Talk_KOREA = " 마찬가지로 인과율을 관측할 수 있는 <color=#ffd34c>기계장치의 마왕</color> 역시 절대 이 지점을 놓치지 않으려고 하겠지."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = " 同じく、因果率を観測できる<color=#ffd34c>機械装置の魔王</color>もまた、決してこの時点を見逃しはしないだろう。"
L29_1.m_Talk_ENG = "Likewise, the <color=#ffd34c>Demon Lord of Machinery</color> will attempt to never miss this point as she can also observe causality."
L29_1.m_Talk_TWN = "並且，那個同樣能預測因果律的<color=#ffd34c>機械魔王</color>也不會放過這個……"
L29_1.m_Talk_SCN = "并且，那个同样能预测因果律的<color=#ffd34c>机械魔王</color>也不会放过这个……"
L29_1.m_Talk_DEU = "Likewise, the <color=#ffd34c>Demon Lord of Machinery</color> will attempt to never miss this point as she can also observe causality."
L29_1.m_Talk_FRA = "Likewise, the <color=#ffd34c>Demon Lord of Machinery</color> will attempt to never miss this point as she can also observe causality."
